interface CacheEntry { key: string }
interface AuthHint { key: string }

const hint: AuthHint = { key: "sess-1" };
const entry: CacheEntry = hint; // TS: OK — same shape

// Emitted JavaScript:
// const hint = { key: "sess-1" };
// const entry = hint;
// No CacheEntry or AuthHint exists at runtime

class CacheEntry { public string Key { get; init; } = ""; }
class AuthHint   { public string Key { get; init; } = ""; }

AuthHint hint = new() { Key = "sess-1" };
// CacheEntry entry = hint; // Compiler error
CacheEntry entry = new() { Key = hint.Key };

class AuthHandler {
  provider = "base";
  parse(raw) { return raw; }
}
class LtiHandler extends AuthHandler {
  provider = "lti";
  parse(raw) { return { kind: "lti", raw }; }
}

const h = new LtiHandler();
console.log(h.parse("jwt")); // { kind: 'lti', raw: 'jwt' }

// Mutable at runtime — unlike C# sealed virtual slots:
AuthHandler.prototype.parse = () => ({ hijacked: true });
console.log(h.parse("jwt")); // still LtiHandler.parse — own shadow
// but new instances after prototype patch behave differently

// JavaScript runtime
class Client {
  #secret = "live";
  get preview() { return this.#secret.slice(0, 2); }
}

const c = new Client();
console.log(c.preview); // li
// c.#secret — SyntaxError

// TypeScript 'private token' emits as public this.token in JS
// C# private string Token — CLR blocks cross-type access at runtime

class SqlAttemptStore {
  async saveAsync(attempt) {
    return attempt;
  }
}

const service = new SqlAttemptStore();

// Works — constructor function exists
if (service instanceof SqlAttemptStore) {
  await service.saveAsync({ id: "a-1" });
}

// Does NOT exist at runtime:
// if (service instanceof IAttemptStore) — ReferenceError

// Duck typing — no compiler guarantee:
if (typeof service.saveAsync === "function") {
  await service.saveAsync({ id: "a-2" });
}
